#!/usr/bin/env python3
"""Self-verifying compressed exact original CPython source for TMR-3/064.

Run: python experiments/tmr/tmr3_boomerang_frontier064.py --output /tmp/raw064.json
The embedded source (not this wrapper) is the original local executable.
"""
from __future__ import annotations
import base64, hashlib, zlib
PACKED = (
    ""
    ""
    ""
    ""
    ""
)
original = zlib.decompress(base64.b64decode("".join(PACKED)))
assert hashlib.sha256(original).hexdigest() == "7baa92171b5a7efb923b01abd3bd828ecb6e475d371f2928d8b3d67f3e51b1cb", "wrong original source SHA256"
exec(compile(original.decode("utf-8"), "tmr3_boomerang_frontier064_original.py", "exec"), {"__name__":"__main__", "__file__":__file__})
